CREATE OR REPLACE FUNCTION public.seed_leittext_catalog(p_raw text) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE it jsonb; h text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Nicht angemeldet.'; END IF;
  h := encode(sha256(convert_to(p_raw, 'UTF8')), 'hex');
  IF NOT (h = ANY (ARRAY['e37d0ef0571ffc179b15e2f43eb2587c6cbda548ea2de7eb0a741c2aaaaee967','0fbdff1279bd1a446d63a8265fba2d28cf3580f1f6d1335e791fa595f3fdaa2f','ace40b8de9c7d725c6017b470de1c06019a6b836b1439d2722fc0fa432721264','22837f9a4c5946af0c8b2ed3f7c9aa78f41e882f9ef087e6e42823fd2c021d5e','3a141defa1b12fd32b431d894d01999778e906fe6857ef209dbf4dae5a6bb255','96af7d39e5c04531c7fd258d9de65be5bf34b63e5151c3ac5f62b1148e34ff88','beccd1d595984f83ddca116ecdc879a7f9f268a4e6555db0a45bebc2aedb703f','5854eb78d940f5bbf10c3ea25f957b3ab19afbb888a9ea5a2bcf5c6b3e644d4d','5780d17a170149de917685fd6c5aac85d8a05571df40ca77bb019eb9931cc998','bc8629b3d87cc31382a020e9293c18c38a2895cd091d7a697c436bd3b5bf3d71','17ed2be3162f2081902f7d6724a875ad70dd7b810d5442123a443b63c6728ae2','210d5743047a62b7f650fde9275f8922164623acbb4f82448579434b2f569856','896add8500bc14b3bed39c23c61279063594f9437d1e58fc4ed38ef66757447b','57b23772866421ef517c50cd6d38c4fe930ee612d087f987485f9f6aeee84311','3bfd51dad4d165d0cb10ab324dd1b3002edac8d0f27cf06ec68643f83bbb3265','aa31ba02e3ea5401f5b04726f26012cab902a1839d7e21e1ac5ecd6aafe1500d','b59885587985913f1582fc7a3c7e6bdb897c2300c7f3840e7b4e3af7a34f16db','adbb55e285e7c4c097f44f6881abad96f89272b1fe4b0dbc94bca0c6647a02d2','cca2d47c41f945e8e723bcf699ff19e641da22ce79fb25ccdce63db4e89c59c6','02bb6f033791b3c244bc8e2603c6aafe0c77271c4202036a64d7f1d9e81883a3','678fc59b819c79779c017fa7e09279f5b3bb195523c4c49b3a404f19ea2ef6bf','08aaebb1e346da0bf0a9c967f2b38e3c6cc94482145c845ae0680a3a0c988fb2','7e18d813f089a9e693c97be533d902196e75d82a1be4b8ed8f43b1007ecf5716','f66d6f20477ff112a29736830ecea9e53043365309a63349d0646845e4dcc485','463463ac96be713dd17c03c0f8b4e1eb8718a441fe8956c96fce986a8768a458','c2276df9af83e2b5dcd61c94831e8981ff1bf22a70d87df850d271849e4766ce','f4621380b6203b3c8e85cc26cf19037c231529ff786fe771dcb18ac4e37619d5','7fbd30edbe198dffdaf3f74cecd06c8e1f0dbe8122561f19069fce85e13a079e','c9fe28538b3da25cbf0c9de108ec527925b2ec8448883e0f638ccc1f150ab9e0','0c89279d63bd0b0787871a678331bf0