ed13452f5208057219a55d8abb7d00a607d426ba042','b99ac4e3c33922bf06d957bd1a511a49dab3fbdcbbbd3c422dbc9c297cd46d13','4b63e3738fbc6943d7fc76dc036f7cb7b60e887aae89fdef31a2e0b2b66f67e3','9ff042f29f0e11a4329a9b388ab15661c641ffb4d56e5b18b3d2f944cc8e9e34','3c5023c1c9b6b069924e757fd28b3e61cbffefb848e27bb14f57cfddf1713723','60226f8f566677233753745c811a5a6ea2bdd60856dc1b51e5dd950f0c96c849'])) THEN
    RAISE EXCEPTION 'Unbekannter Leittext-Inhalt.';
  END IF;
  it := p_raw::jsonb;
  INSERT INTO public.leittexts (code, title, topic, profession_codes, source_url, stand, order_no, content, sort_order, published)
  VALUES (it->>'code', it->>'title', coalesce(it->>'topic', ''),
          ARRAY(SELECT jsonb_array_elements_text(coalesce(it->'profession_codes', '[]'::jsonb))),
          it->>'source_url', nullif(it->>'stand', ''), nullif(it->>'order_no', ''), it->'content',
          coalesce((it->>'sort_order')::int, 0), true)
  ON CONFLICT (code) DO UPDATE SET
    title = excluded.title, topic = excluded.topic, profession_codes = excluded.profession_codes,
    source_url = excluded.source_url, stand = excluded.stand, order_no = excluded.order_no,
    content = excluded.content, sort_order = excluded.sort_order;
  RETURN it->>'code';
END $$;
REVOKE ALL ON FUNCTION public.seed_leittext_catalog(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.seed_leittext_catalog(text) TO authenticated;